      "originating_execution_ref",
      "originating_daemon_or_provider_operation_ref",
      "environment_ref",
      "session_ref",
      "provider_ref",
      "resource_refs",
      "required_disposition",
      "cause",
      "reclaim_policy_ref",
      "required_authority_refs",
      "lifecycle_head_ref",
      "status",
      "escalation",
      "attempt_count",
      "last_attempt_ref",
      "next_attempt_after",
      "evidence_refs",
